23	/** Shows supported placeholders at the caret after the user types `{{`. */
24	export function MarkdownPlaceholderTypeaheadPlugin() {
25	    const [editor] = useLexicalComposerContext();
26	    const { overlayContainer, placeholders } = useCellValue(markdownPlaceholderConfig$)
27	    const [query, setQuery] = useState('')
28	    const options = useMemo(
29	        () => placeholders
30	            .filter((placeholder) => placeholderMatchesQuery(placeholder, query))
31	            .map((placeholder) => new MarkdownPlaceholderOption(placeholder)),
32	        [placeholders, query],
33	    )
34	
35	    const triggerFn = useCallback<TriggerFn>((text, editor) => {
36	        const match = matchPlaceholderTrigger(text, editor)
37	        if (!match || !placeholders.some((placeholder) => placeholderMatchesQuery(placeholder, match.matchingString))) return null
38	
39	        return match
40	    }, [placeholders])
41	
42	    const handleQueryChange = useCallback((nextQuery: string | null) => {
43	        setQuery(nextQuery ?? '')
44	    }, [])
45	
46	    const handleDraftReset = useCallback(() => {
47	        setQuery('');
48	        return false;
49	    }, []);
50	    useEffect(() => editor.registerCommand(RESET_MARKDOWN_DRAFT_COMMAND, handleDraftReset, COMMAND_PRIORITY_HIGH),
51	        [editor, handleDraftReset]);
52	
53	    const handleSelectOption = useCallback((
54	        option: MarkdownPlaceholderOption,
55	        textNodeContainingQuery: TextNode | null,
56	        closeMenu: () => void,
57	    ) => {
58	        if (!textNodeContainingQuery) return
59	
60	        textNodeContainingQuery.setTextContent(formatActionPlaceholder(option.placeholder.name))
61	        textNodeContainingQuery.selectEnd()
62	        closeMenu()
63	    }, [])
64	
65	    const renderMenu = useCallback<MenuRenderFn<MarkdownPlaceholderOption>>((anchorElementRef, itemProps) => {
66	        if (!anchorElementRef.current || itemProps.options.length === 0) return null
67	
68	        return createPortal(
69	            <MarkdownPlaceholderMenu
70	                onHighlight={itemProps.setHighlightedIndex}
71	                onSelect={itemProps.selectOptionAndCleanUp}
72	                options={itemProps.options}
73	                selectedIndex={itemProps.selectedIndex}
74	            />,
75	            anchorElementRef.current,
76	        )
77	    }, [])
78	
79	    return (
80	        <LexicalTypeaheadMenuPlugin<MarkdownPlaceholderOption>
81	            menuRenderFn={renderMenu}
82	            onQueryChange={handleQueryChange}
83	            onSelectOption={handleSelectOption}
84	            options={options}
85	            parent={overlayContainer ?? undefined}
86	            triggerFn={triggerFn}
87	        />
88	    )
89	}
