34	        [repositoryFiles],
35	    )
36	
37	    const handleQueryChange = useCallback((nextQuery: string | null) => {
38	        setQuery(nextQuery)
39	    }, [])
40	
41	    const handleOpen = useCallback((resolution: MenuResolution) => {
42	        if (hasCapturedAnchorRef.current) return
43	
44	        hasCapturedAnchorRef.current = true
45	        const { height, left, top, width } = resolution.getRect()
46	        setAnchorRect({ height, left, top, width })
47	    }, [])
48	
49	    const handleClose = useCallback(() => {
50	        hasCapturedAnchorRef.current = false
51	        setAnchorRect(null)
52	    }, [])
53	
